import Index from "views/Index.js";
import Profile from "views/examples/Profile.js";
import Register from "views/examples/Register.js";
import Login from "views/examples/Login.js";
import Tables from "views/examples/Tables.js";
import CarbonDataInput from "views/examples/datainput";
import CarbonRedemption from "views/examples/redeemcredits";
import { Navigate } from "react-router-dom"; // Import Navigate
import { auth } from "../firebase"; // Ensure Firebase Auth is imported

const user = auth.currentUser; // Check if user is logged in

var routes = [
  {
    path: "/index",
    name: "EcoCred",
    icon: "ni ni-tv-2 text-primary",
    component: user ? <Index /> : <Navigate to="/auth/login" />,
    layout: "/admin",
  },
  {
    path: "/tables",
    name: "Carbon Actions Log",
    icon: "ni ni-bullet-list-67 text-red",
    component: user ? <Tables /> : <Navigate to="/auth/login" />,
    layout: "/admin",
  },
  {
    path: "/datainput",
    name: "Carbon Input",
    icon: "ni ni-single-02 text-yellow",
    component: user ? <CarbonDataInput /> : <Navigate to="/auth/login" />,
    layout: "/admin",
  },
  {
    path: "/redeemcredits",
    name: "Redeem",
    icon: "ni ni-single-02 text-yellow",
    component: user ? <CarbonRedemption /> : <Navigate to="/auth/login" />,
    layout: "/admin",
  },
  {
    path: "/user-profile",
    name: "User Profile",
    icon: "ni ni-single-02 text-yellow",
    component: user ? <Profile /> : <Navigate to="/auth/login" />,
    layout: "/admin",
  },
  {
    path: "/login",
    name: "Login",
    icon: "ni ni-key-25 text-info",
    component: <Login />,
    layout: "/auth",
  },
  {
    path: "/register",
    name: "Register",
    icon: "ni ni-circle-08 text-pink",
    component: <Register />,
    layout: "/auth",
  },
];

// Ensure default redirection
routes.unshift({
  path: "/",
  component: !user ? <Navigate to="/auth/login" /> : <Navigate to="/admin/index" />,
  layout: "/",
});

export default routes;
